function findFirstSlot(layout, w, h) {
  const maxY = layout.reduce((m, l) => Math.max(m, l.y + l.h), 0);
  for (let y = 0; y <= maxY + h; y++) {
    for (let x = 0; x <= GRID_COLS - w; x++) {
      const fits = !layout.some(l =>
        l.x < x + w && l.x + l.w > x &&
        l.y < y + h && l.y + l.h > y
      );
      if (fits) return { x, y };
    }
  }
  return { x: 0, y: maxY };
}

function reducer(state, action) {
  switch (action.type) {

    case 'SET_MODE':
      return { ...state, mode: action.payload, editingWidgetId: null, developerTab: action.payload === 'developer' ? 'dashboard' : state.developerTab };

    case 'SET_DEVELOPER_TAB':
      return { ...state, developerTab: action.payload };

    case 'SET_THEME': {
      const { __advancedStats, ...themeUpdates } = action.payload;
      const dashUpdates = { theme: { ...state.dashboard.theme, ...themeUpdates } };
      if (__advancedStats !== undefined) dashUpdates.advancedStats = __advancedStats;
      return {
        ...state,
        dashboard: { ...state.dashboard, ...dashUpdates },
      };
    }

    // ── Datasets ──────────────────────────────────────────────
    case 'LOAD_DATASET': {
      const { name, data, source } = action.payload;
      const id = uuid();
      const dicts = cloneDicts(state.colStore.dicts);
      const table = buildTable(id, name, data, dicts);
      const ds = makeDataset(id, name, data, table, source);
      return {
        ...state,
        datasets: [...state.datasets, ds],
        activeDatasetId: id,
        colStore: { dicts, tables: { ...state.colStore.tables, [id]: table } },
      };
    }

    case 'DELETE_DATASET': {
      const datasets = state.datasets.filter(d => d.id !== action.payload);
      const activeDatasetId = state.activeDatasetId === action.payload
        ? (datasets[0]?.id ?? null) : state.activeDatasetId;
      const tables = { ...state.colStore.tables };
      delete tables[action.payload];
      return { ...state, datasets, activeDatasetId, colStore: { ...state.colStore, tables } };
    }

    case 'RENAME_DATASET': {
      const { id: renId, name: renName } = action.payload;
      const datasets = state.datasets.map(d => d.id === renId ? { ...d, name: renName } : d);
      const tables = { ...state.colStore.tables };
      if (tables[renId]) tables[renId] = { ...tables[renId], name: renName };
      return { ...state, datasets, colStore: { ...state.colStore, tables } };
    }

    case 'SET_ACTIVE_DATASET':
      return { ...state, activeDatasetId: action.payload };

    // ── Transforms ────────────────────────────────────────────
    case 'ADD_TRANSFORM': {
      const dicts = cloneDicts(state.colStore.dicts);
      const tables = { ...state.colStore.tables };
      const datasets = state.datasets.map(d => {
        if (d.id !== action.payload.datasetId) return d;
        const updated = recompute(
          { ...d, transforms: [...d.transforms, { ...action.payload.transform, id: uuid() }] },
          dicts
        );
        tables[d.id] = updated.table;
        return updated;
      });
      return { ...state, datasets, colStore: { dicts, tables } };
    }

    case 'REMOVE_TRANSFORM': {
      const dicts = cloneDicts(state.colStore.dicts);
      const tables = { ...state.colStore.tables };
      const datasets = state.datasets.map(d => {
        if (d.id !== action.payload.datasetId) return d;
        const updated = recompute(
          { ...d, transforms: d.transforms.filter(t => t.id !== action.payload.transformId) },
          dicts
        );
        tables[d.id] = updated.table;
        return updated;
      });
      return { ...state, datasets, colStore: { dicts, tables } };
    }

    case 'UPDATE_TRANSFORM': {
      const dicts = cloneDicts(state.colStore.dicts);
      const tables = { ...state.colStore.tables };
      const datasets = state.datasets.map(d => {
        if (d.id !== action.payload.datasetId) return d;
        const transforms = d.transforms.map(t =>
          t.id === action.payload.transformId ? { ...t, ...action.payload.updates } : t
        );
        const updated = recompute({ ...d, transforms }, dicts);
        tables[d.id] = updated.table;
        return updated;
      });
      return { ...state, datasets, colStore: { dicts, tables } };
    }

    case 'MOVE_TRANSFORM': {
      const dicts = cloneDicts(state.colStore.dicts);
      const tables = { ...state.colStore.tables };
      const datasets = state.datasets.map(d => {
        if (d.id !== action.payload.datasetId) return d;
        const ts = [...d.transforms];
        const { from, to } = action.payload;
        ts.splice(to, 0, ts.splice(from, 1)[0]);
        const updated = recompute({ ...d, transforms: ts }, dicts);
        tables[d.id] = updated.table;
        return updated;
      });
      return { ...state, datasets, colStore: { dicts, tables } };
    }

    // ── Pages ─────────────────────────────────────────────────
    case 'ADD_PAGE': {
      const page = makePage({ name: `Page ${state.dashboard.pages.length + 1}` });
      return {
        ...state,
        dashboard: {
          ...state.dashboard,
          pages: [...state.dashboard.pages, page],
          currentPageId: page.id,
        },
        editingWidgetId: null,
      };
    }

    case 'REMOVE_PAGE': {
      if (state.dashboard.pages.length <= 1) return state;
      const pages = state.dashboard.pages.filter(p => p.id !== action.payload);
      const currentPageId = state.dashboard.currentPageId === action.payload
        ? pages[pages.length - 1].id : state.dashboard.currentPageId;
      return {
        ...state,
        dashboard: { ...state.dashboard, pages, currentPageId },
        editingWidgetId: null,
      };
    }

    case 'RENAME_PAGE': {
      const pages = state.dashboard.pages.map(p =>
        p.id === action.payload.id ? { ...p, name: action.payload.name } : p
      );
      return { ...state, dashboard: { ...state.dashboard, pages } };
    }

    case 'REORDER_PAGE': {
      // payload: { fromId, toId } — move fromId tab to the position of toId
      const { fromId, toId } = action.payload;
      if (fromId === toId) return state;
      const pages = [...state.dashboard.pages];
      const fromIdx = pages.findIndex(p => p.id === fromId);
      const toIdx = pages.findIndex(p => p.id === toId);
      if (fromIdx < 0 || toIdx < 0) return state;
      pages.splice(fromIdx, 1);
      pages.splice(toIdx, 0, state.dashboard.pages[fromIdx]);
      return { ...state, dashboard: { ...state.dashboard, pages } };
    }

    case 'SET_CURRENT_PAGE':
      return {
        ...state,
        dashboard: { ...state.dashboard, currentPageId: action.payload },
        editingWidgetId: null,
      };

    // ── Widgets ───────────────────────────────────────────────
    case 'ADD_WIDGET': {
      const widget = defaultWidget({
        datasetId: state.datasets[0]?.id ?? null,
        ...action.payload,
      });
      const pageLayout = state.dashboard.pages.find(p => p.id === state.dashboard.currentPageId)?.layout ?? [];
      const { x: slotX, y: slotY } = findFirstSlot(pageLayout, 12, 5);
      const layoutItem = { i: widget.id, x: slotX, y: slotY, w: 12, h: 5 };
      const pages = state.dashboard.pages.map(p =>
        p.id === state.dashboard.currentPageId
          ? { ...p, widgets: [...p.widgets, widget], layout: [...p.layout, layoutItem] }
          : p
      );
      return {
        ...state,
        dashboard: { ...state.dashboard, pages },
        developerTab: 'dashboard',
        editingWidgetId: widget.id,
      };
    }

    case 'UPDATE_WIDGET': {
      const pages = state.dashboard.pages.map(p => ({
        ...p,
        widgets: p.widgets.map(w =>
          w.id === action.payload.id ? { ...w, ...action.payload.updates } : w
        ),
      }));
      return { ...state, dashboard: { ...state.dashboard, pages } };
    }

    case 'REMOVE_WIDGET': {
      const id = action.payload;
      const pages = state.dashboard.pages.map(p => ({
        ...p,
        widgets: p.widgets.filter(w => w.id !== id),
        layout: p.layout.filter(l => l.i !== id),
      }));
      const editingWidgetId = state.editingWidgetId === id ? null : state.editingWidgetId;
      return { ...state, dashboard: { ...state.dashboard, pages }, editingWidgetId };
    }

    case 'ADD_TO_CAROUSEL': {
      // payload: { carouselId, widgetId }
      const { carouselId, widgetId } = action.payload;
      const pages = state.dashboard.pages.map(p => {
        const srcWidget = p.widgets.find(w => w.id === widgetId);
        if (!srcWidget) return p;
        // Convert widget to a slide (same fields, new id)
        const slide = { ...srcWidget, id: uuid() };
        delete slide.slides; // prevent nesting carousels
        const updatedWidgets = p.widgets
          .filter(w => w.id !== widgetId)
          .map(w => w.id === carouselId ? { ...w, slides: [...(w.slides || []), slide] } : w);
        return {
          ...p,
          widgets: updatedWidgets,
          layout: p.layout.filter(l => l.i !== widgetId),
        };
      });
      const editingWidgetId = state.editingWidgetId === widgetId ? carouselId : state.editingWidgetId;
      return { ...state, dashboard: { ...state.dashboard, pages }, editingWidgetId };
    }

    case 'EJECT_FROM_CAROUSEL': {
      // payload: { carouselId, slideId }
      const { carouselId, slideId } = action.payload;
      let ejected = null;
      const pages = state.dashboard.pages.map(p => {
        const carousel = p.widgets.find(w => w.id === carouselId);
        if (!carousel) return p;
        const slide = (carousel.slides || []).find(s => s.id === slideId);
        if (!slide) return p;
        ejected = { ...slide, id: uuid() };
        const carouselLayout = p.layout.find(l => l.i === carouselId) || { x: 0, y: 0, w: 12, h: 5 };
        const { x: slotX, y: slotY } = findFirstSlot(p.layout, carouselLayout.w, carouselLayout.h);
        return {
          ...p,
          widgets: [
            ...p.widgets.map(w => w.id === carouselId
              ? { ...w, slides: (w.slides || []).filter(s => s.id !== slideId) }
              : w
            ),
            ejected,
          ],
          layout: [...p.layout, { i: ejected.id, x: slotX, y: slotY, w: carouselLayout.w, h: carouselLayout.h }],
        };
      });
      return { ...state, dashboard: { ...state.dashboard, pages }, editingWidgetId: ejected?.id ?? state.editingWidgetId };
    }

    case 'DUPLICATE_WIDGET': {
      let newWidget = null;
      const pages = state.dashboard.pages.map(p => {
        const src = p.widgets.find(w => w.id === action.payload);
        if (!src) return p;
        newWidget = { ...src, id: uuid(), title: src.title + ' (copy)' };
        const srcLayout = p.layout.find(l => l.i === action.payload);
        const sw = srcLayout?.w ?? 12;
        const sh = srcLayout?.h ?? 5;
        const { x: slotX, y: slotY } = findFirstSlot(p.layout, sw, sh);
        return {
          ...p,
          widgets: [...p.widgets, newWidget],
          layout: [...p.layout, { i: newWidget.id, x: slotX, y: slotY, w: sw, h: sh }],
        };
      });
      if (!newWidget) return state;
      return { ...state, dashboard: { ...state.dashboard, pages }, editingWidgetId: newWidget.id };
    }

    case 'MOVE_WIDGET_TO_PAGE': {
      const { widgetId, targetPageId, copy } = action.payload;
      let srcWidget = null;
      let srcLayout = null;
      // Find the widget and its layout item in any page
      for (const p of state.dashboard.pages) {
        const w = p.widgets.find(w => w.id === widgetId);
        if (w) {
          srcWidget = w;
          srcLayout = p.layout.find(l => l.i === widgetId);
          break;
        }
      }
      if (!srcWidget) return state;
      const newId = copy ? uuid() : srcWidget.id;
      const movedWidget = copy
        ? { ...srcWidget, id: newId, title: srcWidget.title + ' (copy)' }
        : srcWidget;
      const pages = state.dashboard.pages.map(p => {
        if (p.id === targetPageId) {
          const sw = srcLayout?.w ?? 12;
          const sh = srcLayout?.h ?? 5;
          const { x: slotX, y: slotY } = findFirstSlot(p.layout, sw, sh);
          return {
            ...p,
            widgets: [...p.widgets, movedWidget],
            layout: [...p.layout, { i: newId, x: slotX, y: slotY, w: sw, h: sh }],
          };
        }
        if (!copy) {
          // Remove from source page
          return {
            ...p,
            widgets: p.widgets.filter(w => w.id !== widgetId),
            layout: p.layout.filter(l => l.i !== widgetId),
          };
        }
        return p;
      });
      const editingWidgetId = state.editingWidgetId === widgetId && !copy ? null : state.editingWidgetId;
      return { ...state, dashboard: { ...state.dashboard, pages }, editingWidgetId };
    }

    case 'UPDATE_LAYOUT': {
      const pages = state.dashboard.pages.map(p =>
        p.id === state.dashboard.currentPageId ? { ...p, layout: action.payload } : p
      );
      return { ...state, dashboard: { ...state.dashboard, pages } };
    }

    case 'SET_DASHBOARD_TITLE':
      return { ...state, dashboard: { ...state.dashboard, title: action.payload } };

    case 'SET_EDITING_WIDGET':
      return { ...state, editingWidgetId: action.payload };

    case 'MAXIMIZE_WIDGET':
      return { ...state, maximizedWidgetId: action.payload };

    case 'NAVIGATE_TO_WIDGET': {
      // Switch page + maximize
      const { pageId, widgetId } = action.payload;
      return {
        ...state,
        dashboard: { ...state.dashboard, currentPageId: pageId },
        maximizedWidgetId: widgetId,
      };
    }

    // ── Filters (legacy, kept for backward compat) ─────────────
    case 'SET_FILTER':
      return { ...state, filters: { ...state.filters, [action.payload.id]: action.payload } };

    case 'REMOVE_FILTER': {
      const filters = { ...state.filters };
      delete filters[action.payload];
      return { ...state, filters };
    }

    case 'CLEAR_FILTERS':
      return { ...state, filters: {} };

    // ── Associative selections ────────────────────────────────
    case 'SET_SELECTION': {
      const { field, values } = action.payload;
      // Allow empty arrays (creates the pill); null/undefined removes the field
      if (values == null) {
        const sel = { ...state.selections };
        delete sel[field];
        return { ...state, selections: sel };
      }
      return { ...state, selections: { ...state.selections, [field]: values } };
    }

    case 'TOGGLE_SELECTION': {
      const { field, value } = action.payload;
      const strVal = String(value);
      const current = state.selections[field] || [];
      const next = current.includes(strVal)
        ? current.filter(v => v !== strVal)
        : [...current, strVal];
      // Keep the pane with empty array (= "all") instead of removing it
      return { ...state, selections: { ...state.selections, [field]: next } };
    }

    case 'CLEAR_SELECTION': {
      // Reset to "all" (empty array) — keeps the pane visible
      return { ...state, selections: { ...state.selections, [action.payload]: [] } };
    }

    case 'REMOVE_SELECTION': {
      // Completely remove the selection pane
      const sel = { ...state.selections };
      delete sel[action.payload];
      return { ...state, selections: sel };
    }

    case 'CLEAR_ALL_SELECTIONS': {
      // Reset all panes to "all" (empty arrays) — keep panes visible
      const cleared = {};
      for (const field of Object.keys(state.selections)) cleared[field] = [];
      return { ...state, selections: cleared };
    }

    case 'RESTORE_SELECTIONS':
      return { ...state, selections: action.payload };

    // ── Bookmarks ─────────────────────────────────────────────
    case 'SAVE_BOOKMARK': {
      const { id: bmId, name: bmName } = action.payload;
      const existing = (state.dashboard.bookmarks || []).find(b => b.id === bmId);
      const bookmarks = existing
        ? (state.dashboard.bookmarks || []).map(b => b.id === bmId ? { ...b, name: bmName, selections: state.selections } : b)
        : [...(state.dashboard.bookmarks || []), { id: uuid(), name: bmName, selections: state.selections }];
      return { ...state, dashboard: { ...state.dashboard, bookmarks } };
    }

    case 'DELETE_BOOKMARK': {
      const bookmarks = (state.dashboard.bookmarks || []).filter(b => b.id !== action.payload);
      return { ...state, dashboard: { ...state.dashboard, bookmarks } };
    }

    case 'LOAD_BOOKMARK': {
      const bm = (state.dashboard.bookmarks || []).find(b => b.id === action.payload);
      if (!bm) return state;
      return { ...state, selections: bm.selections || {} };
    }

    // ── Render pause ──────────────────────────────────────────
    case 'SET_RENDER_PAUSED':
      return { ...state, renderPaused: action.payload };

    // ── Dimension colors ───────────────────────────────────────
    case 'SET_MODEL_POSITIONS':
      return { ...state, dashboard: { ...state.dashboard, modelPositions: action.payload } };

    case 'SET_DIMENSION_COLOR': {
      const { value, colorDef } = action.payload; // colorDef: { type: 'custom', color } | { type: 'palette', index }
      return {
        ...state,
        dashboard: {
          ...state.dashboard,
          dimensionColors: { ...state.dashboard.dimensionColors, [value]: colorDef },
        },
      };
    }

    case 'REMOVE_DIMENSION_COLOR': {
      const dc = { ...state.dashboard.dimensionColors };
      delete dc[action.payload];
      return { ...state, dashboard: { ...state.dashboard, dimensionColors: dc } };
    }

    case 'TOGGLE_CONSISTENT_COLOR_FIELD': {
      const field = action.payload;
      const current = state.dashboard.consistentColorFields || [];
      const isEnabling = !current.includes(field);
      const next = isEnabling ? [...current, field] : current.filter(f => f !== field);
      // When enabling: purge stale palette-type dimension color entries (from older code versions)
      let dimColors = state.dashboard.dimensionColors;
      if (isEnabling) {
        const cleaned = Object.fromEntries(Object.entries(dimColors).filter(([, v]) => v?.type !== 'palette'));
        if (Object.keys(cleaned).length !== Object.keys(dimColors).length) dimColors = cleaned;
      }
      return { ...state, dashboard: { ...state.dashboard, consistentColorFields: next, dimensionColors: dimColors } };
    }

    // ── Field synonyms ────────────────────────────────────────
    case 'SET_FIELD_SYNONYMS': {
      const { field, synonyms } = action.payload;
      const fs = { ...state.dashboard.fieldSynonyms };
      if (!synonyms || synonyms.length === 0) {
        delete fs[field];
      } else {
        fs[field] = synonyms;
      }
      return { ...state, dashboard: { ...state.dashboard, fieldSynonyms: fs } };
    }

    // ── Shared dimensions (dashboard-level) ─────────────────
    case 'SET_HIERARCHIC_DIMENSIONS':
      return { ...state, dashboard: { ...state.dashboard, hierarchicDimensions: action.payload } };

    case 'SET_CYCLIC_DIMENSIONS':
      return { ...state, dashboard: { ...state.dashboard, cyclicDimensions: action.payload } };

    case 'DRILL_DOWN': {
      const { id: drillId, field: drillField, value: drillValue } = action.payload;
      const hds = (state.dashboard.hierarchicDimensions || []).map(hd => {
        if (hd.id !== drillId) return hd;
        if (hd.currentLevel >= hd.levels.length - 1) return hd;
        return { ...hd, currentLevel: hd.currentLevel + 1, filters: [...(hd.filters || []), { field: drillField, value: String(drillValue) }] };
      });
      return { ...state, dashboard: { ...state.dashboard, hierarchicDimensions: hds } };
    }

    case 'DRILL_UP': {
      const hds2 = (state.dashboard.hierarchicDimensions || []).map(hd => {
        if (hd.id !== action.payload) return hd;
        if (hd.currentLevel <= 0) return { ...hd, currentLevel: 0, filters: [] };
        return { ...hd, currentLevel: hd.currentLevel - 1, filters: (hd.filters || []).slice(0, -1) };
      });
      return { ...state, dashboard: { ...state.dashboard, hierarchicDimensions: hds2 } };
    }

    case 'DRILL_TO_LEVEL': {
      const { id: dtlId, level: dtlLevel } = action.payload;
      const hds3 = (state.dashboard.hierarchicDimensions || []).map(hd => {
        if (hd.id !== dtlId) return hd;
        return { ...hd, currentLevel: dtlLevel, filters: (hd.filters || []).slice(0, dtlLevel) };
      });
      return { ...state, dashboard: { ...state.dashboard, hierarchicDimensions: hds3 } };
    }

    case 'CYCLE_DIMENSION': {
      const { id: cycId, direction = 1 } = action.payload;
      const cds = (state.dashboard.cyclicDimensions || []).map(cd => {
        if (cd.id !== cycId) return cd;
        const next = ((cd.activeIndex || 0) + direction + cd.fields.length) % cd.fields.length;
        return { ...cd, activeIndex: next };
      });
      return { ...state, dashboard: { ...state.dashboard, cyclicDimensions: cds } };
    }

    // ── Clustering ─────────────────────────────────────────────
    case 'RUN_CLUSTERING': {
      const { datasetId, fields, config } = action.payload;
      const dicts = cloneDicts(state.colStore.dicts);
      const tables = { ...state.colStore.tables };
      let clusterStats = null;
      const datasets = state.datasets.map(d => {
        if (d.id !== datasetId) return d;
        const { data: clustered, stats } = runClustering(d.data, fields, config);
        clusterStats = stats;
        // Write cluster column back to originalData too, so transforms don't erase it
        const colName = config.columnName || '_cluster';
        const labelMap = new Map(clustered.map((r, i) => [i, r[colName]]));
        const newOriginal = d.originalData.map((row, i) => ({ ...row, [colName]: labelMap.get(i) ?? null }));
        const updated = recompute({ ...d, originalData: newOriginal }, dicts);
        tables[d.id] = updated.table;
        return updated;
      });
      // Store stats on the action for the UI to read via callback
      if (action.onComplete) action.onComplete(clusterStats);
      return { ...state, datasets, colStore: { dicts, tables } };
    }

    case 'REMOVE_COLUMN': {
      const { datasetId, column } = action.payload;
      const dicts = cloneDicts(state.colStore.dicts);
      const tables = { ...state.colStore.tables };
      const datasets = state.datasets.map(d => {
        if (d.id !== datasetId) return d;
        const newOriginal = d.originalData.map(row => {
          const { [column]: _, ...rest } = row;
          return rest;
        });
        const updated = recompute({ ...d, originalData: newOriginal }, dicts);
        tables[d.id] = updated.table;
        return updated;
      });
      return { ...state, datasets, colStore: { dicts, tables } };
    }

    // ── Import ────────────────────────────────────────────────
    case 'IMPORT_STATE': {
      const { datasets, dashboard } = action.payload;
      // Support both old format (widgets/layout) and new format (pages)
      let pages = dashboard.pages;
      if (!pages) {
        const migratedPage = makePage({
          name: 'Page 1',
          widgets: dashboard.widgets || [],
          layout: dashboard.layout || [],
        });
        pages = [migratedPage];
      }
      const currentPageId = pages[0]?.id ?? uuid();
      const theme = dashboard.theme || defaultTheme;
      const dicts = {};
      const tables = {};
      const processed = datasets.map(d => {
        const updated = recompute({ ...d, transforms: d.transforms ?? [] }, dicts);
        tables[d.id] = updated.table;
        return updated;
      });
      // Convert old filters to selections if present
      let selections = {};
      if (action.payload.selections) {
        selections = action.payload.selections;
      } else if (action.payload.filters) {
        for (const f of Object.values(action.payload.filters)) {
          if (f.filterType === 'categorical' && f.values?.length > 0) {
            selections[f.field] = f.values;
          }
        }
      }
      return {
        ...initialState,
        mode: 'viewer',
        datasets: processed,
        activeDatasetId: processed[0]?.id ?? null,
        dashboard: { ...dashboard, pages, currentPageId, theme },
        colStore: { dicts, tables },
        selections,
        fileOrigin: action.payload.fileOrigin || null,
      };
    }

    case 'NEW_DASHBOARD': {
      const page = makePage({ name: 'Page 1' });
      return {
        ...initialState,
        dashboard: {
          ...initialState.dashboard,
          title: 'My Dashboard',
          pages: [page],
          currentPageId: page.id,
        },
      };
    }

    case 'SET_FILE_ORIGIN':
      return { ...state, fileOrigin: action.payload };

    case 'RESTORE_STATE':
      return action.payload;

    case 'RESTORE_FILTERS':
      return { ...state, filters: action.payload };

    default:
      return state;
  }
}

const UNDO_LIMIT = 50;
const UNDOABLE_ACTIONS = new Set([
  'ADD_WIDGET', 'UPDATE_WIDGET', 'REMOVE_WIDGET', 'DUPLICATE_WIDGET',
  'ADD_TO_CAROUSEL', 'EJECT_FROM_CAROUSEL',
  'MOVE_WIDGET_TO_PAGE', 'UPDATE_LAYOUT',
  'ADD_PAGE', 'REMOVE_PAGE', 'RENAME_PAGE', 'REORDER_PAGE',
  'SET_THEME', 'SET_DASHBOARD_TITLE',
  'LOAD_DATASET', 'DELETE_DATASET', 'RENAME_DATASET',
  'ADD_TRANSFORM', 'REMOVE_TRANSFORM', 'UPDATE_TRANSFORM', 'MOVE_TRANSFORM',
  'SET_DIMENSION_COLOR', 'REMOVE_DIMENSION_COLOR', 'TOGGLE_CONSISTENT_COLOR_FIELD',
  'SET_FIELD_SYNONYMS',
  'RUN_CLUSTERING', 'REMOVE_COLUMN',
]);

const FILTER_ACTIONS = new Set(['SET_FILTER', 'REMOVE_FILTER', 'CLEAR_FILTERS']);
const SELECTION_ACTIONS = new Set(['SET_SELECTION', 'TOGGLE_SELECTION', 'CLEAR_SELECTION', 'REMOVE_SELECTION', 'CLEAR_ALL_SELECTIONS']);

const STORAGE_KEY = 'ytics_dashboard';

export function saveDashboard(state) {
  try {
    const payload = {
      datasets: state.datasets.map(d => ({
        id: d.id, name: d.name, data: d.originalData, transforms: d.transforms,
      })),
      dashboard: state.dashboard,
      selections: state.selections,
    };
    const json = JSON.stringify(payload);
    localStorage.setItem(STORAGE_KEY, json);
    return true;
  } catch (err) {
    console.error('Save failed:', err);
    return err.message || 'unknown error';
  }
}

function loadSaved() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    return JSON.parse(raw);
  } catch { return null; }
}

export function AppProvider({ children }) {
  const [state, rawDispatch] = useReducer(reducer, initialState, () => {
    const saved = loadSaved();
    if (!saved) return initialState;
    try {
      const { datasets, dashboard, selections } = saved;
      const dicts = {};
      const tables = {};
      const processed = datasets.map(d => {
        const updated = recompute({ ...d, transforms: d.transforms ?? [] }, dicts);
        tables[d.id] = updated.table;
        return updated;
      });
      const pages = dashboard.pages || [makePage({ name: 'Page 1' })];
      const currentPageId = dashboard.currentPageId || pages[0]?.id;
      return {
        ...initialState,
        datasets: processed,
        activeDatasetId: processed[0]?.id ?? null,
        dashboard: { ...initialState.dashboard, ...dashboard, pages, currentPageId },
        colStore: { dicts, tables },
        selections: selections || {},
      };
    } catch { return initialState; }
  });
  const stateRef = React.useRef(state);
  stateRef.current = state;
  const undoStackRef = React.useRef([]);
  const redoStackRef = React.useRef([]);
  const filterUndoRef = React.useRef([]);
  const filterRedoRef = React.useRef([]);

  const dispatch = useCallback((action) => {
    // ── Developer undo/redo ──
    if (action.type === 'UNDO') {
      if (undoStackRef.current.length === 0) return;
      redoStackRef.current = [...redoStackRef.current.slice(-(UNDO_LIMIT - 1)), stateRef.current];
      rawDispatch({ type: 'RESTORE_STATE', payload: undoStackRef.current.pop() });
      return;
    }
    if (action.type === 'REDO') {
      if (redoStackRef.current.length === 0) return;
      undoStackRef.current = [...undoStackRef.current.slice(-(UNDO_LIMIT - 1)), stateRef.current];
      rawDispatch({ type: 'RESTORE_STATE', payload: redoStackRef.current.pop() });
      return;
    }
    // ── Viewer filter/selection undo/redo ──
    if (action.type === 'FILTER_UNDO' || action.type === 'SELECTION_UNDO') {
      if (filterUndoRef.current.length === 0) return;
      filterRedoRef.current = [...filterRedoRef.current.slice(-(UNDO_LIMIT - 1)), stateRef.current.selections];
      rawDispatch({ type: 'RESTORE_SELECTIONS', payload: filterUndoRef.current.pop() });
      return;
    }
    if (action.type === 'FILTER_REDO' || action.type === 'SELECTION_REDO') {
      if (filterRedoRef.current.length === 0) return;
      filterUndoRef.current = [...filterUndoRef.current.slice(-(UNDO_LIMIT - 1)), stateRef.current.selections];
      rawDispatch({ type: 'RESTORE_SELECTIONS', payload: filterRedoRef.current.pop() });
      return;
    }
    // ── Track undoable actions ──
    if (UNDOABLE_ACTIONS.has(action.type)) {
      undoStackRef.current = [...undoStackRef.current.slice(-(UNDO_LIMIT - 1)), stateRef.current];
      redoStackRef.current = [];
    }
    if (FILTER_ACTIONS.has(action.type) || SELECTION_ACTIONS.has(action.type)) {
      filterUndoRef.current = [...filterUndoRef.current.slice(-(UNDO_LIMIT - 1)), stateRef.current.selections];
      filterRedoRef.current = [];
    }
    rawDispatch(action);
  }, []);

  // Ctrl+Z / Ctrl+Y handler
  useEffect(() => {
    const handler = (e) => {
      const tag = document.activeElement?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
      const key = e.key.toLowerCase();
      const mod = e.ctrlKey || e.metaKey;
      if (!mod) return;

      const isUndo = key === 'z' && !e.shiftKey;
      const isRedo = key === 'y' || (key === 'z' && e.shiftKey);
      if (!isUndo && !isRedo) return;
      e.preventDefault();

      const inViewer = stateRef.current.mode === 'viewer';
      if (isUndo) dispatch({ type: inViewer ? 'SELECTION_UNDO' : 'UNDO' });
      else        dispatch({ type: inViewer ? 'SELECTION_REDO' : 'REDO' });
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [dispatch]);

  // Compute associative state (memoized)
  const associativeState = useMemo(
    () => computeAssociativeState(state.colStore, state.selections),
    [state.colStore, state.selections]
  );

  return <AppContext.Provider value={{ state, dispatch, associativeState }}>{children}</AppContext.Provider>;
}

export function useApp() {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error('useApp must be used inside AppProvider');
  return ctx;
}
